import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/assets/DouBao-%E5%88%9B%E5%BB%BA%E5%AF%86%E9%92%A5.DFDWvLb5.png",n="/newx-doc/assets/DouBao-%E7%94%B3%E8%AF%B7%E6%A8%A1%E5%9E%8B.hNriSxPZ.png",r="/newx-doc/assets/%E5%AD%97%E8%8A%82%E8%B1%86%E5%8C%85-%E5%AE%98%E6%96%B9.Dnii7cn8.png",g=JSON.parse('{"title":"【模型接入】字节豆包","description":"","frontmatter":{},"headers":[],"relativePath":"ai/doubao.md","filePath":"ai/doubao.md","lastUpdated":null}'),d={name:"ai/doubao.md"};function l(h,a,p,c,k,u){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="【模型接入】字节豆包" tabindex="-1">【模型接入】字节豆包 <a class="header-anchor" href="#【模型接入】字节豆包" aria-label="Permalink to &quot;【模型接入】字节豆包&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/doubao</code>，实现 <a href="https://www.volcengine.com/product/doubao" target="_blank" rel="noreferrer">doubao 豆包大模型</a> 的接入：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>Doubao-Seed-2.1-pro、Doubao-Seed-2.1-turbo 等</td><td>DouBaoChatModel</td></tr><tr><td>AI 绘画</td><td>暂未接入</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>由于字节豆包是非开源的模型，所以无法私有化部署，需要去官网申请 API Key，然后通过项目自定义的 DouBaoChatModel 接入。</p><h3 id="_1-1-申请字节密钥" tabindex="-1">1.1 申请字节密钥 <a class="header-anchor" href="#_1-1-申请字节密钥" aria-label="Permalink to &quot;1.1 申请字节密钥&quot;">​</a></h3><p>① 在 <a href="https://www.volcengine.com/experience/ark?utm_term=202502dsinvite&amp;ac=DSASUQY5&amp;rc=BQ4TPVC1" target="_blank" rel="noreferrer">火山引擎</a> 上，注册一个账号。</p><p>② 在 <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey?apikey=%7B%7D" target="_blank" rel="noreferrer">系统设置 -&gt; API Key 管理</a> 上，创建一个 API Key 密钥。</p><p><img src="'+o+'" alt="创建密钥"></p><p>③ 在 <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/model?vendor=Bytedance&amp;view=LIST_VIEW" target="_blank" rel="noreferrer">智能广场 -&gt; 模型广场</a> 上，开通 “Doubao-Seed-2.1-pro” 或 “Doubao-Seed-2.1-turbo” 模型。</p><p><img src="'+n+'" alt="申请模型"></p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+r+`" alt="官方的密钥配置"></p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>doubao-seed-2-1-pro-260628</code></td><td>262144</td></tr><tr><td><code>doubao-seed-2-1-turbo-260628</code></td><td>262144</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>TODO 等待 DouBao ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 DouBaoChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.doubao</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    doubao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 字节豆包</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${DOUBAO_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">doubao-seed-2-1-turbo-260628</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，DouBaoChatModelTests 里有对应的测试用例，可以参考。</p>`,28)])])}const E=e(d,[["render",l]]);export{g as __pageData,E as default};
